cd /Users/smaschek/dev/paigasus/paigasus-core
owner=$(gh repo view --json owner --jq '.owner.login'); repo=$(gh repo view --json name --jq '.name'); pr=49
gh api graphql -F owner="$owner" -F repo="$repo" -F pr="$pr" -f query='query($owner:String!,$repo:String!,$pr:Int!){
  repository(owner:$owner,name:$repo){
    pullRequest(number:$pr){
      reviewThreads(first:100){
        nodes{
          id isResolved isOutdated
          comments(first:1){ nodes{ databaseId path line startLine originalLine author{login} body } }
        }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes
  | map(select(.isResolved==false and .isOutdated==false and (.comments.nodes[0].author.login|test("coderabbit"))))
  | "UNRESOLVED CODERABBIT THREADS: \(length)\n" + (map("\n=== threadId=\(.id)\n  file=\(.comments.nodes[0].path):\(.comments.nodes[0].line // .comments.nodes[0].originalLine)\n  commentId=\(.comments.nodes[0].databaseId)") | join("\n"))'

cd /Users/smaschek/dev/paigasus/paigasus-core
owner=$(gh repo view --json owner --jq '.owner.login'); repo=$(gh repo view --json name --jq '.name'); pr=49
echo "=== ALL review threads (any state) ==="
gh api graphql -F owner="$owner" -F repo="$repo" -F pr="$pr" -f query='query($owner:String!,$repo:String!,$pr:Int!){
  repository(owner:$owner,name:$repo){ pullRequest(number:$pr){
    reviewThreads(first:100){ nodes{ isResolved isOutdated comments(first:1){nodes{path author{login}}} } } } }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes | "total threads: \(length)"'
echo "=== CodeRabbit review/comment summaries (first 1500 chars each) ==="
gh pr view "$pr" --json reviews,comments --jq '
  [ (.reviews[]?|select(.author.login|test("coderabbit"))|{kind:"review",body}),
    (.comments[]?|select(.author.login|test("coderabbit"))|{kind:"comment",body}) ]
  | .[] | "--- \(.kind) ---\n\(.body[0:1500])"'

cd /Users/smaschek/dev/paigasus/paigasus-core
owner=$(gh repo view --json owner --jq '.owner.login'); repo=$(gh repo view --json name --jq '.name'); pr=49
echo "=== unresolved CodeRabbit threads now ==="
gh api graphql -F owner="$owner" -F repo="$repo" -F pr="$pr" -f query='query($owner:String!,$repo:String!,$pr:Int!){
  repository(owner:$owner,name:$repo){ pullRequest(number:$pr){
    reviewThreads(first:100){ nodes{ isResolved isOutdated comments(first:1){nodes{author{login} path}} } } } }
}' --jq '[.data.repository.pullRequest.reviewThreads.nodes[]|select(.isResolved==false and (.comments.nodes[0].author.login|test("coderabbit")))] | length'
echo "=== latest CodeRabbit reviews (commit + first line) ==="
gh api repos/$owner/$repo/pulls/$pr/reviews --jq '[.[]|select(.user.login|test("coderabbit"))]|.[-3:]|.[]|{submitted_at, commit_id: .commit_id[0:7], head: (.body|split("\n")[0])}'
echo "=== HEAD commit ==="; git rev-parse --short HEAD

